.card-actions {
    position: absolute;
    top: 10px;
    right: 10px;
    opacity: 0;
    transition: opacity 0.2s;
    display: flex;
    gap: 5px;
}

/* Mostrar acciones al pasar el mouse */
.card:hover .card-actions {
    opacity: 1;
}

.action-btn {
    background: rgba(0, 0, 0, 0.6);
    color: white;
    border: none;
    padding: 5px 8px;
    cursor: pointer;
    border-radius: 4px;
    font-size: 1em;
}

/* Modal Styling */
.modal {
    display: none; /* Por defecto oculto */
    position: fixed;
    z-index: 100;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    overflow: auto;
    background-color: rgba(0, 0, 0, 0.4); /* Overlay */
}

.modal-content {
    background-color: #fefefe;
    margin: 5% auto; /* Centrado vertical y horizontal */
    padding: 20px;
    border-radius: 10px;
    width: 80%;
    max-width: 500px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
}

.modal-content h2 {
    margin-top: 0;
    color: #102C54;
}

.form-group {
    margin-bottom: 15px;
}

.form-group label {
    display: block;
    margin-bottom: 5px;
    font-weight: bold;
}

.form-group input[type="text"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 10px;
    border: 1px solid #ccc;
    border-radius: 4px;
    box-sizing: border-box;
}

/* Botones del modal */
.modal-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 20px;
}

.btn-primary, .btn-secondary {
    padding: 10px 20px;
    border: none;
    cursor: pointer;
    border-radius: 5px;
    transition: background-color 0.2s;
}

.btn-primary {
    background-color: #3498db;
    color: white;
}

.btn-secondary {
    background-color: #ccc;
    color: #333;
}

/* Estilo de la columna Pendiente */
#addCardBtnBottom {
    padding: 8px;
    border: 1px dashed #ccc;
    border-radius: 8px;
    cursor: pointer;
    margin: 10px 15px 20px 15px; /* Espaciado */
    background-color: white;
}

/* R2, R11: Botón 'Agregar tarjeta' en Pendiente */
#addCardBtnBottom.hidden {
    display: none;
}
